# Zwischenfrüchte: Gültigkeit (Anrechenbarkeit als Zwischenfrucht) und
# Förderverpflichtungen während des Begrünungszeitraums (Kapitel 5.2 Merkblatt,
# SRL Punkt 2.7 „Für Zwischenfrüchte gelten folgende Bedingungen“).
package o6_7.catch_crop

import data.o6_7.lib

cc := lib.params.catch_crop

# Bei Untersaaten gilt die Ernte der Hauptfrucht als Anlagedatum.
effective_start(s) := s.undersown_host_harvest_date if {
	s.is_undersown == true
} else := s.start_date

start_year(s) := lib.year_of(effective_start(s))

start_day(s) := lib.day(effective_start(s))

# Eine im Mehrfachantrag beantragte Begrünung zählt als Hauptfrucht.
effective_kind(s) := "main_crop" if {
	s.kind == "catch_crop"
	s.declared_in_mfa == true
} else := s.kind

is_catch_crop(s) if effective_kind(s) == "catch_crop"

sown_by_mixture_cutoff(s) if start_day(s) <= lib.mmdd_day(start_year(s), cc.mixture_cutoff_mmdd)

# Ersteinstieg: Anlage vor Vertragsbeginn (1.1. des ersten Teilnahmejahres).
pre_contract(s) if {
	first := input.farm.oepul.o6_7.first_contract_year
	start_day(s) < lib.mmdd_day(first, "01-01")
}

mixture(s) := object.get(s, "mixture", {})

mixture_requirement_met(s) if {
	object.get(mixture(s), "partner_count", 0) >= cc.min_mixture_partners
	object.get(mixture(s), "plant_family_count", 0) >= cc.min_plant_families
}

# Vor 2025: ausschließlich winterhart; ab Antragsjahr 2025: überwiegend
# winterhart (abfrostende Komponenten unter 50 %).
winter_hardy_requirement_met(s) if {
	start_year(s) >= cc.mostly_winter_hardy_from_year
	object.get(mixture(s), "frost_killed_share", 1) < cc.max_frost_killed_share_from_2025_exclusive
}

winter_hardy_requirement_met(s) if {
	start_year(s) < cc.mostly_winter_hardy_from_year
	object.get(mixture(s), "frost_killed_share", 1) == 0
}

proper_sowing(s) if s.proper_sowing == true

# Dürre 2026: kein Beanstanden bei ordnungsgemäßer Anlage, wenn Feldaufgang
# keine Flächendeckung erreicht bzw. Ausfallgetreide die 50 %-Grenze überschreitet.
drought_2026_relief(s) if {
	start_year(s) == lib.params.drought_2026.year
	proper_sowing(s)
}

volunteer_cereal_drought_relief(s) if {
	drought_2026_relief(s)
	mixture(s).cereal_excess_from_volunteer == true
}

overwintering(s) if not s.end_date

overwintering(s) if lib.year_of(s.end_date) > start_year(s)

catch_crop_segments[key] := e if {
	some key, e in lib.segments
	is_catch_crop(e.seg)
}

# ---------------------------------------------------------------------------
# Anrechenbarkeit als Zwischenfrucht
# ---------------------------------------------------------------------------

invalid_reasons[key] contains "volunteer_only" if {
	some key, e in catch_crop_segments
	mixture(e.seg).is_volunteer_only == true
}

invalid_reasons[key] contains "cereal_maize_share_over_50_percent" if {
	some key, e in catch_crop_segments
	s := e.seg
	lib.approx_gt(object.get(mixture(s), "cereal_maize_share", 0), cc.max_cereal_maize_share)
	not mixture(s).green_rye_varieties_only == true
	not volunteer_cereal_drought_relief(s)
}

invalid_reasons[key] contains "sown_after_october_15" if {
	some key, e in catch_crop_segments
	s := e.seg
	not pre_contract(s)
	start_day(s) > lib.mmdd_day(start_year(s), cc.latest_sowing_mmdd)
}

invalid_reasons[key] contains "mixture_partners_insufficient" if {
	some key, e in catch_crop_segments
	s := e.seg
	not pre_contract(s)
	sown_by_mixture_cutoff(s)
	not mixture_requirement_met(s)
}

invalid_reasons[key] contains "not_winter_hardy_after_september_20" if {
	some key, e in catch_crop_segments
	s := e.seg
	not pre_contract(s)
	not sown_by_mixture_cutoff(s)
	not winter_hardy_requirement_met(s)
}

invalid_reasons[key] contains "pre_contract_mixture_not_compliant" if {
	some key, e in catch_crop_segments
	s := e.seg
	pre_contract(s)
	not mixture_requirement_met(s)
	not winter_hardy_requirement_met(s)
}

invalid_reasons[key] contains "minimum_duration_42_days_not_met" if {
	some key, e in catch_crop_segments
	s := e.seg
	s.end_date
	lib.day(s.end_date) - start_day(s) < cc.min_duration_days
}

invalid_reasons[key] contains "broken_before_february_15" if {
	some key, e in catch_crop_segments
	s := e.seg
	not sown_by_mixture_cutoff(s)
	s.end_date
	lib.day(s.end_date) < lib.mmdd_day(start_year(s) + 1, cc.earliest_break_after_late_sowing_mmdd)
}

invalid_reasons[key] contains "threshed" if {
	some key, e in catch_crop_segments
	e.seg.threshed == true
}

invalid_reasons[key] contains "threshed" if {
	some key, e in catch_crop_segments
	some op in object.get(e.seg, "operations", [])
	op.type == "threshing"
}

invalid_reasons[key] contains "no_full_coverage" if {
	some key, e in catch_crop_segments
	s := e.seg
	s.full_coverage_achieved == false
	not drought_2026_relief(s)
}

valid[key] if {
	some key, _ in catch_crop_segments
	not invalid_reasons[key]
}

# ---------------------------------------------------------------------------
# Förderverpflichtungen während des Begrünungszeitraums
# ---------------------------------------------------------------------------

in_period(s, d) if {
	lib.day(d) > start_day(s)
	not s.end_date
}

in_period(s, d) if {
	lib.day(d) > start_day(s)
	lib.day(d) < lib.day(s.end_date)
}

nitrate_ban_end_day(s) := lib.day(s.nitrate_ban_end_date) if {
	s.nitrate_ban_end_date
} else := lib.day(s.end_date) if {
	s.end_date
} else := lib.year_end_day + 366

mechanical_codes := {m.code | some m in lib.lists.mechanical_removal_methods}

mechanical_removal(s) if s.removal_method in mechanical_codes

care_before_nov_allowed(op) if {
	op.type == "chopping"
	op.ground_near == false
	op.problem_weed in lib.lists.problem_weeds_early_chopping
	op.evidence_kept == true
}

before_care_cutoff(s, op) if lib.day(op.date) <= lib.mmdd_day(start_year(s), cc.overwintering_care_ban_until_mmdd)

cover_or_regrowth_lost(op) if op.cover_maintained == false

cover_or_regrowth_lost(op) if op.regrowth_expected == false

violation(e, rule_id, code, d) := {
	"rule_id": rule_id,
	"parcel_id": e.parcel_id,
	"segment": object.get(e.seg, "segment_id", null),
	"code": code,
	"date": d,
}

violations contains violation(e, "O67-CC-MINERAL-N-BAN", "mineral_n_during_ban", d) if {
	some e in catch_crop_segments
	s := e.seg
	some d in object.get(s, "mineral_n_dates", [])
	lib.day(d) >= start_day(s)
	lib.day(d) <= nitrate_ban_end_day(s)
}

violations contains violation(e, "O67-CC-COMBINED-FERTILISATION", "combined_fertilisation_at_sowing", effective_start(e.seg)) if {
	some e in catch_crop_segments
	e.seg.combined_n_fertilisation_at_sowing == true
}

violations contains violation(e, "O67-CC-PSM-BAN", "psm_during_greening", d) if {
	some e in catch_crop_segments
	s := e.seg
	some d in object.get(s, "psm_dates", [])
	lib.day(d) >= start_day(s)
	not s.end_date
}

violations contains violation(e, "O67-CC-PSM-BAN", "psm_during_greening", d) if {
	some e in catch_crop_segments
	s := e.seg
	some d in object.get(s, "psm_dates", [])
	lib.day(d) >= start_day(s)
	lib.day(d) < lib.day(s.end_date)
}

violations contains violation(e, "O67-CC-PSM-AFTER-NON-MECHANICAL", "psm_before_following_sowing_without_mechanical_removal", d) if {
	some e in catch_crop_segments
	s := e.seg
	s.end_date
	not mechanical_removal(s)
	some d in object.get(s, "psm_dates", [])
	lib.day(d) >= lib.day(s.end_date)
	lib.day(d) < lib.day(s.following_main_crop_sowing_date)
}

violations contains violation(e, "O67-CC-MECHANICAL-REMOVAL", "no_mechanical_removal", e.seg.end_date) if {
	some e in catch_crop_segments
	e.seg.end_date
	not mechanical_removal(e.seg)
}

violations contains violation(e, "O67-CC-MECHANICAL-REMOVAL", "removal_requires_complete_frost_kill", s.end_date) if {
	some e in catch_crop_segments
	s := e.seg
	s.end_date
	some m in lib.lists.mechanical_removal_methods
	m.code == s.removal_method
	m.requires_fully_frost_killed
	not s.fully_frost_killed == true
}

violations contains violation(e, "O67-CC-MECHANICAL-REMOVAL", "removal_requires_only_frost_killing_components", s.end_date) if {
	some e in catch_crop_segments
	s := e.seg
	s.end_date
	some m in lib.lists.mechanical_removal_methods
	m.code == s.removal_method
	m.requires_only_frost_killing_components
	object.get(mixture(s), "frost_killed_share", 0) < 1
}

violations contains violation(e, "O67-CC-TILLAGE-BAN", "tillage_during_greening", op.date) if {
	some e in catch_crop_segments
	some op in object.get(e.seg, "operations", [])
	op.type in {"tillage", "knife_roller"}
	in_period(e.seg, op.date)
}

violations contains violation(e, "O67-CC-ROLLING", "rolling_destroys_cover", op.date) if {
	some e in catch_crop_segments
	some op in object.get(e.seg, "operations", [])
	op.type in {"rolling", "reconsolidation_rolling"}
	in_period(e.seg, op.date)
	op.cover_maintained == false
}

# Anwalzen zur Rückverfestigung nur unmittelbar nach der Anlage; späteres
# Walzen ist bei überwinternden Zwischenfrüchten erst nach dem 31.10. zulässig.
violations contains violation(e, "O67-CC-ROLLING", "reconsolidation_rolling_not_immediate", op.date) if {
	some e in catch_crop_segments
	s := e.seg
	some op in object.get(s, "operations", [])
	op.type == "reconsolidation_rolling"
	in_period(s, op.date)
	lib.day(op.date) - start_day(s) > cc.reconsolidation_rolling_max_days_after_sowing
	overwintering(s)
	before_care_cutoff(s, op)
}

violations contains violation(e, "O67-CC-CARE-BEFORE-NOV", "care_on_overwintering_catch_crop_before_november", op.date) if {
	some e in catch_crop_segments
	s := e.seg
	overwintering(s)
	some op in object.get(s, "operations", [])
	op.type in {"chopping", "maintenance_mowing", "rolling"}
	not op.ground_near == true
	in_period(s, op.date)
	before_care_cutoff(s, op)
	not care_before_nov_allowed(op)
}

violations contains violation(e, "O67-CC-CARE-CONDITIONS", "care_or_use_without_regrowth_or_cover", op.date) if {
	some e in catch_crop_segments
	some op in object.get(e.seg, "operations", [])
	op.type in {"chopping", "maintenance_mowing", "mowing_with_removal", "grazing"}
	not op.ground_near == true
	in_period(e.seg, op.date)
	cover_or_regrowth_lost(op)
}

violations contains violation(e, "O67-CC-GROUND-NEAR-CHOPPING", "ground_near_chopping_before_complete_frost_kill", op.date) if {
	some e in catch_crop_segments
	some op in object.get(e.seg, "operations", [])
	op.type in {"chopping", "maintenance_mowing", "mowing_with_removal"}
	op.ground_near == true
	in_period(e.seg, op.date)
	not op.fully_frost_killed == true
}

violations contains violation(e, "O67-CC-STRIP-TILL-DEEP-LOOSENING", "strip_till_or_deep_loosening_without_cover", op.date) if {
	some e in catch_crop_segments
	some op in object.get(e.seg, "operations", [])
	op.type in {"strip_till_preparation", "deep_loosening"}
	in_period(e.seg, op.date)
	op.cover_maintained == false
}

violations contains violation(e, "O67-CC-STRIP-TILL-DEEP-LOOSENING", "strip_till_preparation_full_area", op.date) if {
	some e in catch_crop_segments
	some op in object.get(e.seg, "operations", [])
	op.type == "strip_till_preparation"
	in_period(e.seg, op.date)
	op.whole_area == true
}

violations contains violation(e, "O67-CC-NO-THRESHING", "threshed_catch_crop_not_declared", object.get(e.seg, "end_date", effective_start(e.seg))) if {
	some key, e in catch_crop_segments
	"threshed" in invalid_reasons[key]
}

violations contains violation(e, "O67-CC-PROBLEM-WEED-EVIDENCE", "early_chopping_without_evidence", op.date) if {
	some e in catch_crop_segments
	s := e.seg
	overwintering(s)
	some op in object.get(s, "operations", [])
	op.type == "chopping"
	op.problem_weed in lib.lists.problem_weeds_early_chopping
	in_period(s, op.date)
	before_care_cutoff(s, op)
	not op.evidence_kept == true
}

# Ist die Anzahl der Mischungspartner am Feld nicht ersichtlich, ist ein
# Saatgutnachweis über Rechnung oder Etikett erforderlich.
violations contains violation(e, "O67-CC-SEED-PROOF", "seed_proof_missing", effective_start(e.seg)) if {
	some e in catch_crop_segments
	s := e.seg
	sown_by_mixture_cutoff(s)
	mixture(s).partners_visible_in_field == false
	not mixture(s).seed_proof_available == true
}

# Teilnahmevoraussetzungen, Antragstellung und Maßnahmenkombination auf
# Betriebsebene (Kapitel 3 und 6 Merkblatt; SRL 1.4, 1.6.1, 1.9.4, 1.10.5.2, 2.7).
package o6_7.eligibility

import data.o6_7.lib

o67 := object.get(input, ["farm", "oepul", "o6_7"], {})

applicant := object.get(input, ["farm", "applicant"], {})

# --- Mindestteilnahme: jedes Teilnahmejahr mindestens 1,50 ha Ackerfläche ---
default access_ok := false

access_ok if lib.arable_area_ha >= lib.params.access.min_arable_area_ha

violations contains {
	"rule_id": "O67-ACCESS-MIN-ARABLE",
	"code": "arable_area_below_1_5_ha",
	"arable_area_ha": lib.arable_area_ha,
} if {
	not access_ok
}

# --- Förderwerbende Personen ---
territorial_exception_applies if {
	some m in lib.lists.territorial_authority_exception_measures
	m.measure_code == lib.params.measure_code
	m.from_year <= lib.year
	_open_or_after(m.to_year)
}

_open_or_after(to_year) if to_year == null

_open_or_after(to_year) if to_year >= lib.year

applicant_type(code) := t if {
	some t in lib.lists.applicant_types
	t.code == code
}

violations contains {
	"rule_id": "O67-APPLICANT-TYPE",
	"code": "applicant_type_not_eligible",
	"legal_form": applicant.legal_form,
} if {
	applicant.legal_form
	not applicant_type(applicant.legal_form)
}

# Für System Immergrün gilt der Ausschluss von Gebietskörperschaften und
# Einrichtungen mit mehr als 25 % Beteiligung von Gebietskörperschaften nicht.
violations contains {
	"rule_id": "O67-APPLICANT-PUBLIC-SHARE",
	"code": "public_body_influence_over_25_percent",
} if {
	t := applicant_type(applicant.legal_form)
	t.public_share_limit_applies
	applicant.public_body_share_percent > lib.params.general.public_body_max_share_percent
	not territorial_exception_applies
}

violations contains {
	"rule_id": "O67-APPLICANT-ACTIVE-FARMER",
	"code": "not_active_farmer_or_no_agricultural_activity",
} if {
	applicant.is_active_farmer == false
}

violations contains {
	"rule_id": "O67-APPLICANT-ACTIVE-FARMER",
	"code": "not_active_farmer_or_no_agricultural_activity",
} if {
	applicant.carries_out_agricultural_activity == false
}

violations contains {
	"rule_id": "O67-APPLICANT-OWN-ACCOUNT",
	"code": "farm_not_managed_in_own_name_and_account",
} if {
	applicant.manages_in_own_name_and_account == false
}

# --- Antragstellung ---
application_deadline_day(contract_year) := lib.mmdd_day(contract_year - 1, lib.params.contract.application_deadline_mmdd)

violations contains {
	"rule_id": "O67-APPLICATION-DEADLINE",
	"code": "measure_application_after_31_december",
	"application_date": o67.application_date,
} if {
	lib.day(o67.application_date) > application_deadline_day(o67.first_contract_year)
}

violations contains {
	"rule_id": "O67-LAST-ENTRY",
	"code": "entry_after_last_entry_year_2027",
	"first_contract_year": o67.first_contract_year,
} if {
	o67.first_contract_year > lib.params.contract.last_entry_contract_year
}

violations contains {
	"rule_id": "O67-LAST-ENTRY",
	"code": "application_after_31_12_2026",
	"application_date": o67.application_date,
} if {
	lib.day(o67.application_date) > lib.day(lib.params.contract.last_application_date)
}

# --- Betriebsmindestgröße im ersten ÖPUL-Teilnahmejahr ---
first_oepul_year if input.farm.oepul.first_participation_year == lib.year

farm_min_size_ok if object.get(input, ["land", "total_area_ha"], 0) >= lib.params.general.first_year_min_total_area_ha

farm_min_size_ok if object.get(input, ["land", "protected_cultivation_area_ha"], 0) >= lib.params.general.first_year_min_protected_cultivation_ha

violations contains {
	"rule_id": "O67-GEN-FARM-MIN-SIZE",
	"code": "farm_below_minimum_size_in_first_oepul_year",
} if {
	first_oepul_year
	not farm_min_size_ok
}

# --- Maßnahmenkombination auf Betriebsebene ---
violations contains {
	"rule_id": "O67-COMB-NOT-WITH-6",
	"code": "simultaneous_participation_in_6_and_7",
} if {
	lib.participates("6")
	lib.participates("7")
}

# Zugangsvoraussetzungen anderer Maßnahmen, die System Immergrün (oder
# Zwischenfruchtanbau) voraussetzen.
violations contains {
	"rule_id": "O67-COMB-PREREQUISITE-FOR-8-16",
	"code": "measure_requires_participation_in_6_or_7",
	"measure_code": req.code,
} if {
	some req in lib.lists.measures_requiring_participation_in_6_or_7
	lib.participates(req.code)
	_requirement_scope_active(req.code)
	not lib.participates("6")
	not lib.participates("7")
}

_requirement_scope_active("16")

_requirement_scope_active("8") if {
	some m in object.get(input, ["farm", "oepul", "participations"], [])
	m.measure_code == "8"
	object.get(m, "year", lib.year) == lib.year
	"mulch_direct_strip_till" in object.get(m, "options", [])
}

# --- Mehrjährigkeit: einjährige Maßnahme ---
is_one_year_measure if {
	some m in lib.lists.one_year_measures
	m.code == lib.params.measure_code
}

# Vertragszeitraum, Verlängerung, Ausstieg/Abmeldung, Maßnahmenwechsel und
# Folgewirkungen (Kapitel 3.1, 6 und 7 Merkblatt; SRL 1.7.1.1, 1.10.5.2).
package o6_7.exit

import data.o6_7.lib

o67 := object.get(input, ["farm", "oepul", "o6_7"], {})

# Abmeldung im Zeitraum 1.1.–31.12. des Förderjahres: Maßnahme im betroffenen
# Förderjahr nicht mehr gültig.
withdrawn_in_year if lib.year_of(o67.withdrawal_date) == lib.year

# Ausstieg erst nach Erfüllung des einjährigen Vertragszeitraums möglich.
withdrawal_effective_year := lib.year_of(o67.withdrawal_date) if o67.withdrawal_date

violations contains {
	"rule_id": "O67-EXIT-DURING-YEAR",
	"code": "withdrawal_during_year_measure_invalid",
	"withdrawal_date": o67.withdrawal_date,
} if {
	withdrawn_in_year
}

# Bei Abmeldung ist „Erosionsschutz Acker“ mit Mulchsaat, Direktsaat oder
# Strip-Till im Folgejahr nicht mehr möglich.
es_acker_mulch_blocked if {
	lib.year_of(o67.withdrawal_date) == lib.year
	not lib.participates("6")
}

violations contains {
	"rule_id": "O67-EXIT-ES-ACKER",
	"code": "erosion_mulch_direct_striptill_after_withdrawal",
} if {
	es_acker_mulch_blocked
	some m in object.get(input, ["farm", "oepul", "participations"], [])
	m.measure_code == "8"
	object.get(m, "year", lib.year) == lib.year
	"mulch_direct_strip_till" in object.get(m, "options", [])
}

# Vertrag erlischt bei Unterschreiten der Mindestteilnahme; ein neuer,
# fristgerechter Maßnahmenantrag ist für eine Wiederteilnahme erforderlich.
contract_lapsed_in_year if lib.arable_area_ha < lib.params.access.min_arable_area_ha

violations contains {
	"rule_id": "O67-CONTRACT-LAPSE-REAPPLY",
	"code": "reentry_without_new_measure_application",
} if {
	lapsed := o67.contract_lapsed_year
	lapsed < lib.year
	not _new_application_after(lapsed)
}

_new_application_after(lapsed) if {
	lib.day(o67.application_date) > lib.mmdd_day(lapsed, "01-01")
	lib.day(o67.application_date) <= lib.mmdd_day(lib.year - 1, lib.params.contract.application_deadline_mmdd)
}

# Wiedereinstieg nach Ausstieg, Ausschluss oder einjähriger Nichtabgabe des
# Mehrfachantrages nur mit neuerlichem Maßnahmenantrag.
violations contains {
	"rule_id": "O67-REENTRY-NEW-APPLICATION",
	"code": "reentry_after_exit_or_missing_mfa_without_new_application",
} if {
	o67.reentry_after_exit_or_missing_mfa == true
	not o67.new_measure_application_submitted == true
}

# Wechsel in „Begrünung von Ackerflächen – Zwischenfruchtanbau“: Beantragung bis
# 31.12. im Maßnahmenantrag, spätester Umstieg 31.12.2026 für 2027.
switch_to_6_valid if {
	d := lib.day(o67.switch_to_6_application_date)
	d <= lib.day(lib.params.contract.last_switch_to_measure_6_date)
}

violations contains {
	"rule_id": "O67-SWITCH-TO-6",
	"code": "switch_to_6_after_last_date",
	"application_date": o67.switch_to_6_application_date,
} if {
	o67.switch_to_6_application_date
	not switch_to_6_valid
}

# Feldfuttermischung nach Hauptkultur, im Frühjahr genutzt und als
# Doppelnutzung beantragt, ist Hauptfrucht: keine Teilnahme an „Erosionsschutz
# Acker“ (Mulchsaat/Direktsaat/Strip-Till) auf dieser Fläche.
violations contains {
	"rule_id": "O67-FIELD-FODDER-DOUBLE-USE",
	"code": "es_acker_mulch_on_double_use_field_fodder",
	"parcel_id": e.parcel_id,
} if {
	some e in lib.segments
	e.seg.double_use_field_fodder == true
	some p in lib.arable_parcels
	p.parcel_id == e.parcel_id
	p.es_acker_mulch_direct_strip_till == true
}

# Automatische Verlängerung um ein weiteres Förderjahr ohne Abmeldung.
auto_renewed_next_year if {
	not o67.withdrawal_date
	not contract_lapsed_in_year
}

# Allgemeine ÖPUL-Bedingungen mit Wirkung auf System Immergrün
# (Allgemeine Teilnahmebedingungen 2026-04; SRL 1.6, 1.7, 1.12) sowie
# Dürre-Erleichterungen 2026 zur Ernteverpflichtung.
package o6_7.general

import data.o6_7.lib

region := object.get(input, ["farm", "region"], {})

parcel_district(p) := p.district if p.district

parcel_district(p) := region.district if not p.district

parcel_state(p) := p.federal_state if p.federal_state

parcel_state(p) := region.federal_state if not p.federal_state

# Gebietskulisse Dürre 2026 (Ernteverpflichtung, automatische höhere Gewalt).
drought_region(state, _) if {
	some r in lib.notices.drought_harvest_exemption_regions
	r.federal_state == state
	r.all_districts == true
}

drought_region(state, district) if {
	some r in lib.notices.drought_harvest_exemption_regions
	r.federal_state == state
	district in r.districts
}

harvest_exempt_drought_2026(p) if {
	lib.year == lib.params.drought_2026.year
	p.no_harvestable_crop_due_to_drought == true
	drought_region(parcel_state(p), parcel_district(p))
}

harvest_exempt(p) if harvest_exempt_drought_2026(p)

harvest_exempt(p) if p.force_majeure_recognised == true

# Mindestbewirtschaftung Ackerflächen (ohne Ackerfutter): Ernte und Verbringen
# des Erntegutes auf zumindest 85 % des Schlages; sonst Code OP erforderlich.
harvest_obligation_breach contains p.parcel_id if {
	some p in lib.arable_parcels
	p.usage_category == "main_crop"
	p.harvested_share < lib.params.general.min_harvest_share_arable
	not harvest_exempt(p)
}

# Unterjährige Weitergabe ohne Weiterführung durch den Übernehmer bis
# Jahresende: betroffene Flächen mit OP-Code, keine Prämie.
transfer_not_continued contains p.parcel_id if {
	some p in lib.arable_parcels
	p.transfer.transferred_during_year == true
	not p.transfer.successor_continues_until_year_end == true
}

violations contains {
	"rule_id": "O67-GEN-HARVEST-OBLIGATION",
	"code": "harvest_below_85_percent_op_code_required",
	"parcel_id": pid,
} if {
	some pid in harvest_obligation_breach
	some p in lib.arable_parcels
	p.parcel_id == pid
	not "OP" in object.get(p, "oepul_codes", [])
}

violations contains {
	"rule_id": "O67-GEN-COMMITMENT-PERIOD",
	"code": "transferred_parcel_not_continued_op_code_required",
	"parcel_id": pid,
} if {
	some pid in transfer_not_continued
	some p in lib.arable_parcels
	p.parcel_id == pid
	not "OP" in object.get(p, "oepul_codes", [])
}

violations contains {
	"rule_id": "O67-GEN-LOCATION-AUSTRIA",
	"code": "parcel_outside_austria",
	"parcel_id": p.parcel_id,
} if {
	some p in lib.arable_parcels
	p.is_in_austria == false
}

# Sanktionsstufen: ab 2027 statt Verwarnung Einbehalt von 1 %.
warning_replaced_by_retention if lib.year >= lib.params.general.warning_replaced_by_retention_from_year

sanction_steps := [s | some s in lib.general.sanction_steps]

sanction_step_reduction(code) := 0.01 if {
	code == "warning"
	warning_replaced_by_retention
} else := s.reduction_share if {
	some s in lib.general.sanction_steps
	s.code == code
}

# Verweigerung der Kontrolle (außer höhere Gewalt): Antrag abzulehnen, keine
# Prämie für das laufende Jahr, bestehende Verträge beendet.
control_refused if {
	input.farm.oepul.control_refused == true
	not input.farm.oepul.control_refusal_force_majeure == true
}

violations contains {
	"rule_id": "O67-GEN-CONTROL-ACCESS",
	"code": "control_refused_application_rejected",
} if {
	control_refused
}

# Prämienberechnung System Immergrün: Prämienband 70–90 €/ha Ackerfläche,
# Einzelflächen-Kombinierbarkeit (Anhang L), OP-/VF-Codes, Nationalparks,
# Betriebsgrößenmodulation und Mindestauszahlungsbetrag.
package o6_7.premium

import data.o6_7.eligibility
import data.o6_7.exit
import data.o6_7.general
import data.o6_7.lib

prem := lib.params.premium

combinable_codes := {c | some c in lib.combinations.o6_7_parcel_combinable_measures}

# Flächencodes, die einer Maßnahme zugeordnet sind (für Anhang L).
code_measure := {"NAT": "18", "EBW": "19", "UBB": "1A", "BIO": "1B"}

parcel_measures(p) := {m | some m in object.get(p, "oepul_measures", [])} | {code_measure[c] | some c in object.get(p, "oepul_codes", []); code_measure[c]}

no_premium_reasons[p.parcel_id] contains "op_or_vf_code" if {
	some p in lib.arable_parcels
	some c in object.get(p, "oepul_codes", [])
	c in lib.lists.no_premium_parcel_codes
}

no_premium_reasons[p.parcel_id] contains "measure_specific_op_code" if {
	some p in lib.arable_parcels
	lib.params.measure_code in object.get(p, "op_measure_codes", [])
}

no_premium_reasons[p.parcel_id] contains "other_arable_land" if {
	some p in lib.arable_parcels
	p.usage_category in lib.lists.always_ungreened_usage_categories
}

no_premium_reasons[p.parcel_id] contains sprintf("not_combinable_with_%s", [m]) if {
	some p in lib.arable_parcels
	some m in parcel_measures(p)
	m != lib.params.measure_code
	not m in combinable_codes
}

# Weitergeführte 20-jährige Verpflichtungen (K20) sind auf der Einzelfläche
# mit keinen anderen Maßnahmen kombinierbar.
no_premium_reasons[p.parcel_id] contains "k20_not_combinable" if {
	some p in lib.arable_parcels
	"K20" in object.get(p, "oepul_codes", [])
}

no_premium_reasons[p.parcel_id] contains "national_park_no_premium" if {
	some p in lib.arable_parcels
	p.national_park in lib.lists.no_premium_national_parks
}

no_premium_reasons[p.parcel_id] contains "outside_austria" if {
	some p in lib.arable_parcels
	p.is_in_austria == false
}

no_premium_reasons[p.parcel_id] contains "non_eligible_area_type" if {
	some p in lib.arable_parcels
	p.area_type_code in lib.lists.non_eligible_area_type_codes
}

no_premium_reasons[p.parcel_id] contains "gloez8_npf_catch_crop_2024" if {
	some p in lib.arable_parcels
	lib.year == prem.not_eligible_npf_year
	p.gloez8_npf_variant in lib.lists.gloez8_npf_catch_crop_variants_not_eligible_2024
}

# Grünbrachen sind nicht aktiv bewirtschaftet (keine Prämie), zählen aber als
# begrünte Fläche; Biodiversitätsflächen (DIV) von UBB/BIO sind ausgenommen.
no_premium_reasons[p.parcel_id] contains "green_fallow_not_actively_farmed" if {
	some p in lib.arable_parcels
	p.usage_category == "green_fallow"
	not "DIV" in object.get(p, "oepul_codes", [])
}

no_premium_reasons[pid] contains "harvest_obligation_not_met" if {
	some pid in general.harvest_obligation_breach
}

no_premium_reasons[pid] contains "transferred_without_continuation" if {
	some pid in general.transfer_not_continued
}

eligible_parcels contains p if {
	some p in lib.arable_parcels
	not no_premium_reasons[p.parcel_id]
}

eligible_area_ha := sum([p.area_ha | some p in eligible_parcels])

# Maßnahme im Förderjahr gültig (Vertrag besteht und wurde nicht abgemeldet).
default measure_valid := false

measure_valid if {
	eligibility.access_ok
	not exit.withdrawn_in_year
	not lib.participates("6")
	not general.control_refused
	count({v | some v in eligibility.violations; v.rule_id in _contract_blocking_rules}) == 0
}

_contract_blocking_rules := {
	"O67-APPLICANT-TYPE",
	"O67-APPLICANT-PUBLIC-SHARE",
	"O67-APPLICANT-ACTIVE-FARMER",
	"O67-APPLICATION-DEADLINE",
	"O67-LAST-ENTRY",
	"O67-GEN-FARM-MIN-SIZE",
}

# Betriebsgrößenmodulation auf Basis der Gesamtfläche des Betriebes.
total_area_ha := object.get(input, ["land", "total_area_ha"], lib.arable_area_ha)

bracket_ha(b, total) := max([0, min([total, b.to_ha_inclusive]) - b.from_ha_exclusive]) if b.to_ha_inclusive != null

bracket_ha(b, total) := max([0, total - b.from_ha_exclusive]) if b.to_ha_inclusive == null

modulation_factor_for(total) := 1 if {
	total <= 0
} else := sum([(bracket_ha(b, total) * b.payout_share) | some b in lib.general.modulation_brackets]) / total

modulation_factor := modulation_factor_for(total_area_ha)

rate_eur_per_ha := r if {
	r := input.farm.oepul.o6_7.premium_rate_eur_per_ha
	r >= prem.min_eur_per_ha
	r <= prem.max_eur_per_ha
} else := prem.guaranteed_eur_per_ha

round2(x) := round(x * 100) / 100

premium_eur := round2((eligible_area_ha * rate_eur_per_ha) * modulation_factor) if measure_valid

else := 0

premium_min_eur := round2((eligible_area_ha * prem.min_eur_per_ha) * modulation_factor) if measure_valid

else := 0

premium_max_eur := round2((eligible_area_ha * prem.max_eur_per_ha) * modulation_factor) if measure_valid

else := 0

# Von der Gewährung kann abgesehen werden, wenn der Betrag 50 Euro nicht
# überschreitet.
default below_min_payout := false

below_min_payout if premium_eur <= prem.min_payout_eur

# System Immergrün wird nicht in die Obergrenze für Flächenzahlungen
# eingerechnet.
default excluded_from_payment_cap := false

excluded_from_payment_cap if {
	some c in lib.general.payment_caps
	c.year_from <= lib.year
	_cap_open(c.year_to)
	lib.params.measure_code in c.excluded_measures
}

_cap_open(to_year) if to_year == null

_cap_open(to_year) if to_year >= lib.year

summary := {
	"measure_valid": measure_valid,
	"eligible_area_ha": eligible_area_ha,
	"rate_eur_per_ha": rate_eur_per_ha,
	"modulation_factor": modulation_factor,
	"premium_eur": premium_eur,
	"premium_band_eur": {"min": premium_min_eur, "max": premium_max_eur},
	"below_min_payout": below_min_payout,
	"excluded_from_payment_cap": excluded_from_payment_cap,
	"no_premium_parcels": no_premium_reasons,
}

# Aufzeichnungsverpflichtung (Kapitel 5.3) und Angaben im Mehrfachantrag
# (Kapitel 6) der Maßnahme System Immergrün.
package o6_7.records

import data.o6_7.catch_crop
import data.o6_7.lib

violations contains {
	"rule_id": "O67-RECORDS",
	"code": "farm_field_records_incomplete",
} if {
	input.documentation.field_records_complete == false
}

# Schlagbezogene Aufzeichnungen über Ernte Hauptfrucht, Anlage und Umbruch der
# Zwischenfrucht sowie Anlage der Nachfolge-Hauptfrucht – ganzjährig und für die
# gesamte Ackerfläche (unabhängig von den 85 %).
violations contains {
	"rule_id": "O67-RECORDS",
	"code": "parcel_record_missing",
	"parcel_id": p.parcel_id,
	"event": ev,
} if {
	some p in lib.arable_parcels
	records := object.get(p, ["greening", "records"], {})
	some ev in lib.lists.record_events
	object.get(records, ev, true) == false
}

violations contains {
	"rule_id": "O67-RECORDS",
	"code": "records_not_kept_full_year",
	"parcel_id": p.parcel_id,
} if {
	some p in lib.arable_parcels
	object.get(p, ["greening", "records", "full_year_jan_to_dec"], true) == false
}

# Sämtliche Hauptfrüchte einschließlich Zweitkulturen sind im Mehrfachantrag zu
# beantragen.
violations contains {
	"rule_id": "O67-MFA-MAIN-CROPS",
	"code": "main_crop_not_declared_in_mfa",
	"parcel_id": e.parcel_id,
	"segment": object.get(e.seg, "segment_id", null),
} if {
	some e in lib.segments
	e.seg.kind == "main_crop"
	e.seg.declared_in_mfa == false
}

# Zwischenfrüchte dürfen nicht im Mehrfachantrag beantragt werden; eine
# beantragte Begrünung gilt als Hauptfrucht (Umqualifizierung, kein Verstoß).
reclassified_as_main_crop contains key if {
	some key, e in lib.segments
	e.seg.kind == "catch_crop"
	catch_crop.effective_kind(e.seg) == "main_crop"
}

package o6_7.catch_crop_test

